 "title": "Sum, min, max and average of n integers",
 "src": "src",
 "extra": [],
 "main": "Main",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [],
 "cases": [
  {
   "name": "five numbers on one line",
   "input": "5\n3 1 4 5 2\n",
   "expected": "Sum: 15\nMin: 1\nMax: 5\nAverage: 3.00\n"
  },
  {
   "name": "negative numbers over several lines",
   "input": "4\n-7\n-2 -9\n-3\n",
   "expected": "Sum: -21\nMin: -9\nMax: -2\nAverage: -5.25\n"
  },
  {
   "h": "eyJuYW1lIjoibiA9IDAiLCJpbnB1dCI6IjBcbiIsImV4cGVjdGVkIjoiTm8gZGF0YVxuIn0="
  },
  {
   "h": "eyJuYW1lIjoiYSBzdW0gdGhhdCBvdmVyZmxvd3MgaW50IiwiaW5wdXQiOiIzXG4yMDAwMDAwMDAwIDIwMDAwMDAwMDAgMTk5OTk5OTk5OVxuIiwiZXhwZWN0ZWQiOiJTdW06IDU5OTk5OTk5OTlcbk1pbjogMTk5OTk5OTk5OVxuTWF4OiAyMDAwMDAwMDAwXG5BdmVyYWdlOiAxOTk5OTk5OTk5LjY3XG4ifQ=="
  },
  {
   "h": "eyJuYW1lIjoib25lIG51bWJlciwgbm9uLXRlcm1pbmF0aW5nIGF2ZXJhZ2UiLCJpbnB1dCI6IjNcbjEgMSAyXG4iLCJleHBlY3RlZCI6IlN1bTogNFxuTWluOiAxXG5NYXg6IDJcbkF2ZXJhZ2U6IDEuMzNcbiJ9"
  }
 ]
};

const HERE = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const SHOW = args.includes('--show');
const RECORD = args.includes('--record') ? args[args.indexOf('--record') + 1] : null;
const ONLY = args.includes('--case') ? Number(args[args.indexOf('--case') + 1]) : null;
const WIN = process.platform === 'win32';
const color = process.stdout.isTTY && !process.env.NO_COLOR;
const paint = (c, s) => (color ? `\x1b[${c}m${s}\x1b[0m` : s);
const ok = (s) => paint('32', s), bad = (s) => paint('31', s), dim = (s) => paint('2', s), bold = (s) => paint('1', s);
